'use client';

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "sonner";
import type { SupportRequest, SupportPriority } from "@/hooks/admin/use-admin-support";

interface SubmitSupportRequestArgs {
  subject: string;
  message: string;
  priority: SupportPriority;
}

export function useSubmitSupportRequest() {
  const supabase = createClient();
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({ subject, message, priority }: SubmitSupportRequestArgs) => {
      if (!user) throw new Error("You must be logged in to submit a support request.");

      const { error } = await supabase.from("support_requests").insert({
        user_id: user.id,
        user_email: user.email ?? "",
        subject,
        message,
        priority,
        status: "open",
      });

      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      toast.success("Support request submitted. We'll get back to you soon.");
      queryClient.invalidateQueries({ queryKey: ["support-requests", "my"] });
    },
    onError: (error: Error) => {
      toast.error(`Failed to submit request: ${error.message}`);
    },
  });
}

export function useMySupportRequests() {
  const supabase = createClient();
  const { user } = useAuth();

  return useQuery({
    queryKey: ["support-requests", "my", user?.id],
    queryFn: async () => {
      if (!user) return [] as SupportRequest[];

      const { data, error } = await supabase
        .from("support_requests")
        .select("id, subject, status, priority, created_at")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false })
        .limit(10);

      if (error) throw new Error(error.message);
      return (data ?? []) as Pick<SupportRequest, "id" | "subject" | "status" | "priority" | "created_at">[];
    },
    enabled: !!user,
    staleTime: 60_000,
  });
}

'use client';

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import type { Team, TeamMember, TeamInvite } from "@/types/index";
import type { TeamRow, TeamMemberRow, TeamInviteRow } from "@/types/database";

export const teamKeys = {
  all: ["teams"] as const,
  lists: () => [...teamKeys.all, "list"] as const,
  list: (userId: string) => [...teamKeys.lists(), userId] as const,
  details: () => [...teamKeys.all, "detail"] as const,
  detail: (id: string) => [...teamKeys.details(), id] as const,
  members: (teamId: string) => [...teamKeys.all, "members", teamId] as const,
  invites: (teamId: string) => [...teamKeys.all, "invites", teamId] as const,
};

function rowToTeam(row: TeamRow): Team {
  return {
    id: row.id,
    name: row.name,
    owner_id: row.owner_id,
    logo_url: row.logo_url,
    brand_color: row.brand_color,
    custom_domain: row.custom_domain,
    created_at: row.created_at,
  };
}

interface TeamMemberRowWithProfile extends TeamMemberRow {
  profiles?: {
    full_name: string;
    email: string;
    avatar_url: string | null;
  } | null;
}

function rowToTeamMember(row: TeamMemberRowWithProfile): TeamMember {
  return {
    id: row.id,
    team_id: row.team_id,
    user_id: row.user_id,
    role: row.role,
    joined_at: row.joined_at,
    profile: row.profiles
      ? { full_name: row.profiles.full_name, email: row.profiles.email, avatar_url: row.profiles.avatar_url }
      : undefined,
  };
}

function rowToTeamInvite(row: TeamInviteRow): TeamInvite {
  return {
    id: row.id,
    team_id: row.team_id,
    email: row.email,
    role: row.role,
    token: row.token,
    expires_at: row.expires_at,
    created_at: row.created_at,
  };
}

export function useTeams() {
  const supabase = createClient();
  const { user } = useAuth();

  return useQuery({
    queryKey: teamKeys.list(user?.id ?? ""),
    queryFn: async (): Promise<Team[]> => {
      if (!user?.id) return [];

      const { data, error } = await supabase
        .from("team_members")
        .select("team_id, teams(*)")
        .eq("user_id", user.id)
        .order("joined_at", { ascending: true });

      if (error) throw new Error(error.message);

      return (data ?? [])
        .map((row) => {
          const team = (row as { team_id: string; teams: TeamRow | null }).teams;
          return team ? rowToTeam(team) : null;
        })
        .filter((t): t is Team => t !== null);
    },
    enabled: !!user?.id,
  });
}

export function useTeam(teamId: string | undefined) {
  const supabase = createClient();

  return useQuery({
    queryKey: teamKeys.detail(teamId ?? ""),
    queryFn: async (): Promise<Team | null> => {
      if (!teamId) return null;

      const { data, error } = await supabase
        .from("teams")
        .select("*")
        .eq("id", teamId)
        .single();

      if (error) {
        if (error.code === "PGRST116") return null;
        throw new Error(error.message);
      }

      return rowToTeam(data as TeamRow);
    },
    enabled: !!teamId,
  });
}

export function useTeamMembers(teamId: string | undefined) {
  const supabase = createClient();

  return useQuery({
    queryKey: teamKeys.members(teamId ?? ""),
    queryFn: async (): Promise<TeamMember[]> => {
      if (!teamId) return [];

      const { data, error } = await supabase
        .from("team_members")
        .select("*, profiles(full_name, email, avatar_url)")
        .eq("team_id", teamId)
        .order("joined_at", { ascending: true });

      if (error) throw new Error(error.message);

      return (data as TeamMemberRowWithProfile[]).map(rowToTeamMember);
    },
    enabled: !!teamId,
  });
}

export function useTeamInvites(teamId: string | undefined) {
  const supabase = createClient();

  return useQuery({
    queryKey: teamKeys.invites(teamId ?? ""),
