'use client';

import { Component, type ErrorInfo, type ReactNode } from "react";
import { AlertTriangle } from "lucide-react";

interface Props {
  children: ReactNode;
  fallbackHeight?: number;
}

interface State {
  hasError: boolean;
}

export class ChartErrorBoundary extends Component<Props, State> {
  state: State = { hasError: false };

  static getDerivedStateFromError(): State {
    return { hasError: true };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("Chart render error:", error, info);
  }

  render() {
    if (this.state.hasError) {
      const height = this.props.fallbackHeight ?? 120;
      return (
        <div
          className="flex items-center justify-center gap-2 rounded-lg border border-border/40 bg-muted/20 text-xs text-muted-foreground"
          style={{ height }}
        >
          <AlertTriangle className="h-3.5 w-3.5" />
          Chart unavailable
        </div>
      );
    }
    return this.props.children;
  }
}

'use client';

import { Check, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";
import type { ScanStep } from "@/types";

interface ScanProgressTimelineProps {
  steps: ScanStep[];
  currentStep: number; // 0-indexed, -1 means not started
  className?: string;
}

export function ScanProgressTimeline({
  steps,
  currentStep,
  className,
}: ScanProgressTimelineProps) {
  return (
    <div className={cn("space-y-0", className)}>
      {steps.map((step, index) => {
        const isCompleted = index < currentStep;
        const isActive = index === currentStep;
        const isPending = index > currentStep;

        return (
          <div key={index} className="flex gap-4">
            {/* Timeline line + circle */}
            <div className="flex flex-col items-center">
              <div
                className={cn(
                  "flex h-8 w-8 shrink-0 items-center justify-center rounded-full border-2 transition-all duration-300",
                  isCompleted && "border-success bg-success",
                  isActive && "border-primary bg-primary animate-pulse-ring",
                  isPending && "border-border/50 bg-background"
                )}
              >
                {isCompleted && <Check className="h-4 w-4 text-white" />}
                {isActive && <Loader2 className="h-4 w-4 animate-spin text-white" />}
                {isPending && (
                  <span className="h-2 w-2 rounded-full bg-muted-foreground/30" />
                )}
              </div>
              {/* Connecting line */}
              {index < steps.length - 1 && (
                <div
                  className={cn(
                    "w-0.5 flex-1 min-h-[24px] transition-colors duration-300",
                    isCompleted ? "bg-success" : "bg-border"
                  )}
                />
              )}
            </div>
            {/* Step content */}
            <div className="pb-6 pt-1">
              <p
                className={cn(
                  "text-sm font-medium transition-colors duration-300",
                  isCompleted && "text-success",
                  isActive && "text-foreground",
                  isPending && "text-muted-foreground"
                )}
              >
                {step.label}
                {isCompleted && " — Done"}
                {isActive && "..."}
              </p>
              <p className="mt-0.5 text-xs text-muted-foreground">{step.description}</p>
            </div>
          </div>
        );
      })}
    </div>
  );
}

'use client';

import { getScoreBgColor, getScoreColor, formatScore } from "@/lib/score-utils";
import { CRO_PILLARS } from "@/lib/constants";
import { cn } from "@/lib/utils";
import type { CroPillar } from "@/types";

interface PillarProgressBarProps {
