  const [showForm, setShowForm] = useState(false);
  const { data: webhooks = [], isLoading } = useWebhooks();

  const isPro = isProPlus(profile?.plan ?? "free");

  const content = (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-base font-semibold text-foreground">Webhooks</h2>
          <p className="text-sm text-muted-foreground">
            Get notified when events happen in your account
          </p>
        </div>
        {!showForm && (
          <Button
            size="sm"
            onClick={() => setShowForm(true)}
            disabled={!isPro}
            className="gap-1.5"
          >
            <Plus className="h-4 w-4" />
            Add Webhook
          </Button>
        )}
      </div>

      {/* Inline add form */}
      {showForm && <AddWebhookForm onCancel={() => setShowForm(false)} />}

      {/* Table / states */}
      {isLoading ? (
        <WebhookSkeleton />
      ) : webhooks.length === 0 && !showForm ? (
        <div className="flex flex-col items-center justify-center gap-3 rounded-lg border border-dashed border-border py-10 text-center">
          <div className="flex h-12 w-12 items-center justify-center rounded-full bg-muted">
            <Webhook className="h-5 w-5 text-muted-foreground" />
          </div>
          <div>
            <p className="text-sm font-medium text-foreground">
              No webhooks configured
            </p>
            <p className="mt-0.5 text-xs text-muted-foreground">
              Add one to receive scan results in real time.
            </p>
          </div>
          <Button
            size="sm"
            variant="outline"
            onClick={() => setShowForm(true)}
            disabled={!isPro}
          >
            <Plus className="mr-1.5 h-4 w-4" />
            Add Webhook
          </Button>
        </div>
      ) : webhooks.length > 0 ? (
        <div className="rounded-md border border-border/50 overflow-hidden">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>URL</TableHead>
                <TableHead>Events</TableHead>
                <TableHead>Secret</TableHead>
                <TableHead>Active</TableHead>
                <TableHead className="w-10" />
              </TableRow>
            </TableHeader>
            <TableBody>
              {webhooks.map((endpoint) => (
                <WebhookRow key={endpoint.id} endpoint={endpoint} />
              ))}
            </TableBody>
          </Table>
        </div>
      ) : null}
    </div>
  );

  if (!isPro) {
    return (
      <PremiumLock message="Webhooks are available on Pro and Agency plans">
        {content}
      </PremiumLock>
    );
  }

  return content;
}

'use client';

import { useState } from "react";
import { Copy, Check, AlertTriangle, Loader2 } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useCreateApiKey } from "@/hooks/use-api-keys";

interface ApiKeyDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function ApiKeyDialog({ open, onOpenChange }: ApiKeyDialogProps) {
  const [name, setName] = useState("My API Key");
  const [generatedKey, setGeneratedKey] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const { mutate: createApiKey, isPending } = useCreateApiKey();

  function handleGenerate() {
    createApiKey(
      { name: name.trim() || "My API Key" },
      {
        onSuccess: ({ fullKey }) => {
          setGeneratedKey(fullKey);
        },
      },
    );
  }

  async function handleCopy() {
    if (!generatedKey) return;
    await navigator.clipboard.writeText(generatedKey);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  function handleClose() {
    setName("My API Key");
    setGeneratedKey(null);
    setCopied(false);
    onOpenChange(false);
  }

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Create API Key</DialogTitle>
          <DialogDescription>
            Generate a new API key for programmatic access to ConvertScan.
          </DialogDescription>
        </DialogHeader>

        {!generatedKey ? (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="key-name">Key Name</Label>
              <Input
                id="key-name"
                placeholder="e.g. Production, CI/CD, My App"
                value={name}
                onChange={(e) => setName(e.target.value)}
                disabled={isPending}
                maxLength={64}
              />
            </div>
          </div>
        ) : (
          <div className="space-y-4">
            <div className="flex items-start gap-2 rounded-lg border border-amber-200 bg-amber-50 p-3">
              <AlertTriangle className="h-4 w-4 shrink-0 text-amber-600 mt-0.5" />
              <p className="text-sm text-amber-800">
                Save this key now — it will not be shown again.
              </p>
            </div>

            <div className="space-y-2">
              <Label>Your API Key</Label>
              <div className="flex gap-2">
                <code className="flex-1 overflow-auto rounded-md border bg-muted px-3 py-2 font-mono text-sm break-all">
                  {generatedKey}
                </code>
                <Button
                  type="button"
                  variant="outline"
                  size="icon"
                  onClick={() => void handleCopy()}
                  aria-label="Copy API key"
                >
                  {copied ? (
                    <Check className="h-4 w-4 text-green-600" />
                  ) : (
                    <Copy className="h-4 w-4" />
                  )}
                </Button>
              </div>
            </div>
          </div>
        )}

        <DialogFooter>
          {!generatedKey ? (
            <>
              <Button variant="outline" onClick={handleClose} disabled={isPending}>
                Cancel
              </Button>
              <Button onClick={handleGenerate} disabled={isPending || !name.trim()}>
                {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                Generate Key
              </Button>
            </>
          ) : (
            <Button onClick={handleClose} className="w-full">
              Done
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState } from "react";
import { Copy, Check } from "lucide-react";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";

interface CodeBlockProps {
  code: string;
  language?: string;
}

function CodeBlock({ code, language = "bash" }: CodeBlockProps) {
  const [copied, setCopied] = useState(false);

  async function handleCopy() {
    await navigator.clipboard.writeText(code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  return (
    <div className="relative rounded-lg border bg-muted">
      <div className="flex items-center justify-between border-b px-3 py-1.5">
        <span className="text-xs text-muted-foreground font-mono">{language}</span>
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="h-6 w-6"
          onClick={() => void handleCopy()}
          aria-label="Copy code"
        >
          {copied ? (
            <Check className="h-3.5 w-3.5 text-green-600" />
          ) : (
            <Copy className="h-3.5 w-3.5" />
          )}
        </Button>
      </div>
      <pre className="overflow-x-auto p-3 text-xs font-mono leading-relaxed">
        <code>{code}</code>
      </pre>
    </div>
  );
}

const BASE_URL = "https://your-project.supabase.co/functions/v1/api-v1";
const EXAMPLE_KEY = "cs_live_your_api_key_here";

const CREATE_SCAN_CURL = `curl -X POST ${BASE_URL} \\
  -H "Authorization: Bearer ${EXAMPLE_KEY}" \\
  -H "Content-Type: application/json" \\
  -d '{
    "action": "create_scan",
    "url": "https://example.com",
    "page_type": "landing"
  }'`;

const CREATE_SCAN_RESPONSE = `{
  "scan_id": "uuid-here",
  "status": "analyzing",
  "url": "https://example.com",
  "page_type": "landing",
  "created_at": "2026-04-16T10:00:00Z"
}`;

const GET_SCAN_CURL = `curl -X POST ${BASE_URL} \\
  -H "Authorization: Bearer ${EXAMPLE_KEY}" \\
  -H "Content-Type: application/json" \\
  -d '{
    "action": "get_scan",
    "scan_id": "your-scan-id"
  }'`;

const GET_SCAN_RESPONSE = `{
  "scan": {
    "id": "uuid",
    "url": "https://example.com",
    "status": "completed",
    "overall_score": 72,
    "issues_found": 8,
    "critical_issues": 2,
    "created_at": "2026-04-16T10:00:00Z"
  },
  "results": [
    {
      "pillar": "cta_effectiveness",
      "score": 65,
      "weight": 0.20,
      "benchmark": 70,
      "findings": [...]
    }
  ]
}`;

const LIST_SCANS_CURL = `curl -X POST ${BASE_URL} \\
  -H "Authorization: Bearer ${EXAMPLE_KEY}" \\
  -H "Content-Type: application/json" \\
  -d '{
    "action": "list_scans",
    "page": 1,
    "limit": 20
  }'`;

const LIST_SCANS_RESPONSE = `{
  "scans": [
    {
      "id": "uuid",
      "url": "https://example.com",
      "page_type": "landing",
      "status": "completed",
      "overall_score": 72,
      "created_at": "2026-04-16T10:00:00Z"
    }
  ],
  "pagination": {
    "page": 1,
    "limit": 20,
    "total": 42,
    "total_pages": 3
  }
}`;

const GET_REPORT_CURL = `curl -X POST ${BASE_URL} \\
  -H "Authorization: Bearer ${EXAMPLE_KEY}" \\
  -H "Content-Type: application/json" \\
  -d '{
    "action": "get_report",
    "scan_id": "your-scan-id"
  }'`;

const GET_REPORT_RESPONSE = `{
  "scan": { ... },
  "pillar_results": [
    {
      "pillar": "value_proposition",
      "score": 78,
      "weight": 0.18,
      "benchmark": 72,
      "findings": [
        {
          "id": "f_vp_01",
          "title": "Headline lacks specificity",
          "severity": "warning",
          "recommendation": "...",
          "ai_suggestion": "..."
        }
      ]
    }
  ],
  "copy_rewrites": [
    {
      "element_type": "headline",
      "original": "Welcome to our platform",
      "suggested": "Turn clicks into customers with AI-powered CRO",
      "reasoning": "Specificity increases conversion by ~18%"
    }
  ]
}`;

interface Endpoint {
  value: string;
  method: string;
  title: string;
  description: string;
  curlExample: string;
  responseExample: string;
}

const ENDPOINTS: Endpoint[] = [
  {
    value: "create-scan",
    method: "POST",
    title: "Create Scan",
    description: "Submit a URL for CRO analysis. Returns a scan_id immediately while analysis runs asynchronously.",
    curlExample: CREATE_SCAN_CURL,
    responseExample: CREATE_SCAN_RESPONSE,
  },
  {
    value: "get-scan",
    method: "POST",
    title: "Get Scan",
    description: "Retrieve a scan by ID with its current status and pillar results. Poll until status is 'completed' or 'failed'.",
    curlExample: GET_SCAN_CURL,
    responseExample: GET_SCAN_RESPONSE,
  },
  {
    value: "list-scans",
    method: "POST",
    title: "List Scans",
    description: "Paginated list of your scans ordered by creation date (newest first). Max 50 per page.",
    curlExample: LIST_SCANS_CURL,
    responseExample: LIST_SCANS_RESPONSE,
  },
  {
    value: "get-report",
    method: "POST",
    title: "Get Report",
    description: "Full report for a completed scan: scan metadata, all pillar results with findings, and AI copy rewrites.",
    curlExample: GET_REPORT_CURL,
    responseExample: GET_REPORT_RESPONSE,
  },
];

export function ApiDocumentation() {
  return (
    <div className="space-y-4">
      <div className="rounded-lg border bg-muted/40 p-4 text-sm space-y-1.5">
        <p className="font-medium">Base URL</p>
        <code className="font-mono text-xs text-muted-foreground break-all">{BASE_URL}</code>
        <p className="text-muted-foreground text-xs mt-2">
          All requests use <code className="font-mono">POST</code> with an{" "}
          <code className="font-mono">action</code> field in the JSON body. Authenticate
          using your API key in the <code className="font-mono">Authorization</code> header.
        </p>
      </div>

      <Accordion type="single" collapsible className="space-y-2">
        {ENDPOINTS.map((endpoint) => (
          <AccordionItem
            key={endpoint.value}
            value={endpoint.value}
            className="rounded-lg border px-4"
          >
            <AccordionTrigger className="hover:no-underline py-4">
              <div className="flex items-center gap-3">
                <Badge variant="outline" className="font-mono text-xs shrink-0">
                  {endpoint.method}
                </Badge>
                <span className="font-medium text-sm text-left">{endpoint.title}</span>
              </div>
            </AccordionTrigger>
            <AccordionContent className="pb-4 space-y-4">
              <p className="text-sm text-muted-foreground">{endpoint.description}</p>

              <div className="space-y-2">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
                  Request
                </p>
                <CodeBlock code={endpoint.curlExample} language="bash" />
              </div>

              <div className="space-y-2">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
                  Response
                </p>
                <CodeBlock code={endpoint.responseExample} language="json" />
              </div>
            </AccordionContent>
          </AccordionItem>
        ))}
      </Accordion>
    </div>
  );
}

