234	export function AnalyticsCorrelation({ url }: AnalyticsCorrelationProps) {
235	  const { isConnected, isLoading: connectionLoading } = useGa4Connection();
236	  const { data, isLoading, isError, setupRequired, errorMessage, notConnected } =
237	    useAnalyticsData(url);
238	
239	  // While checking connection status
240	  if (connectionLoading) {
241	    return <AnalyticsSkeleton />;
242	  }
243	
244	  // Not connected to GA4
245	  if (!isConnected || notConnected) {
246	    return <NotConnectedState />;
247	  }
248	
249	  // Connected but GA4 property ID not configured
250	  if (setupRequired) {
251	    return <SetupRequiredState />;
252	  }
253	
254	  // Loading analytics data
255	  if (isLoading) {
256	    return <AnalyticsSkeleton />;
257	  }
258	
259	  // API error or token expired
260	  if (isError || errorMessage) {
261	    return <ErrorMessageState message={errorMessage ?? "Unable to load analytics data."} />;
262	  }
263	
264	  // No data available for this URL
265	  if (!data) {
266	    return (
267	      <Card className="border-border/50 shadow-soft">
268	        <CardContent className="flex items-center gap-3 py-6">
269	          <BarChart2 className="h-5 w-5 shrink-0 text-muted-foreground" />
270	          <p className="text-sm text-muted-foreground">
271	            No GA4 data available for this URL in the last 30 days.
272	          </p>
273	        </CardContent>
274	      </Card>
275	    );
276	  }
277	
278	  return <MetricsDisplay metrics={data} />;
279	}
