55	  const isPending = createGroup.isPending || scanAll.isPending;
56	
57	  function validate(): boolean {
58	    const nextErrors: Record<string, string> = {};
59	
60	    if (!groupName.trim()) {
61	      nextErrors["name"] = "Group name is required";
62	    }
63	
64	    const normalizedPrimary = normalizeUrl(primaryUrl);
65	    if (!normalizedPrimary || !isValidUrl(normalizedPrimary)) {
66	      nextErrors["primary"] = "Enter a valid URL (e.g. https://yoursite.com)";
67	    }
68	
69	    competitorUrls.forEach((url, idx) => {
70	      if (!url.trim()) return; // empty slots are fine — skipped below
71	      const normalized = normalizeUrl(url);
72	      if (!isValidUrl(normalized)) {
73	        nextErrors[`competitor_${idx}`] = "Enter a valid URL";
74	      }
75	    });
76	
77	    setErrors(nextErrors);
78	    return Object.keys(nextErrors).length === 0;
79	  }
80	
81	  async function handleSubmit(e: React.FormEvent) {
82	    e.preventDefault();
83	    if (!validate()) return;
84	
85	    const normalizedPrimary = normalizeUrl(primaryUrl);
86	    const normalizedCompetitors = competitorUrls
87	      .map(normalizeUrl)
88	      .filter((url) => url && isValidUrl(url));
89	
90	    if (normalizedCompetitors.length === 0) {
91	      toast.error("Add at least one competitor URL");
92	      return;
93	    }
94	
95	    try {
96	      const group = await createGroup.mutateAsync({
97	        name: groupName.trim(),
98	        primary_url: normalizedPrimary,
99	        competitor_urls: normalizedCompetitors,
100	      });
101	
102	      toast.success("Group created — starting scans...");
103	
104	      // Fire-and-don't-await: scan all URLs in background
105	      // This is intentional — page loads immediately, scans update when done
106	      scanAll.mutate(group, {
107	        onSuccess: () => toast.success(`All scans complete for "${group.name}"`),
108	        onError: () => toast.error("Some scans failed — retry from the group card"),
109	      });
110	
111	      setOpen(false);
112	      resetForm();
113	    } catch {
114	      // error toast handled by mutation
115	    }
116	  }
117	
118	  function resetForm() {
119	    setGroupName("My Competitors");
120	    setPrimaryUrl("");
121	    setCompetitorUrls([""]);
122	    setErrors({});
123	  }
124	
125	  function addCompetitor() {
126	    if (competitorUrls.length >= MAX_COMPETITORS) return;
127	    setCompetitorUrls((prev) => [...prev, ""]);
128	  }
129	
130	  function removeCompetitor(index: number) {
131	    setCompetitorUrls((prev) => prev.filter((_, i) => i !== index));
132	    setErrors((prev) => {
133	      const next = { ...prev };
134	      delete next[`competitor_${index}`];
135	      return next;
136	    });
137	  }
138	
139	  function updateCompetitor(index: number, value: string) {
140	    setCompetitorUrls((prev) => prev.map((u, i) => (i === index ? value : u)));
141	    if (errors[`competitor_${index}`]) {
142	      setErrors((prev) => {
143	        const next = { ...prev };
144	        delete next[`competitor_${index}`];
145	        return next;
146	      });
147	    }
148	  }
149	
150	  return (
151	    <Dialog open={open} onOpenChange={(v) => { setOpen(v); if (!v) resetForm(); }}>
152	      <DialogTrigger asChild>
153	        {trigger ?? (
154	          <Button>
155	            <Swords className="mr-2 h-4 w-4" />
156	            New Comparison
157	          </Button>
158	        )}
159	      </DialogTrigger>
160	
161	      <DialogContent className="sm:max-w-[520px]">
162	        <form onSubmit={(e) => void handleSubmit(e)}>
163	          <DialogHeader>
164	            <DialogTitle>Create Competitor Group</DialogTitle>
165	            <DialogDescription>
166	              Add your URL and up to 4 competitors. We'll scan all of them and generate a side-by-side CRO comparison.
167	            </DialogDescription>
168	          </DialogHeader>
169	
170	          <div className="mt-5 space-y-5">
171	            {/* Group name */}
172	            <div className="space-y-1.5">
173	              <Label htmlFor="group-name">Group name</Label>
174	              <Input
175	                id="group-name"
176	                value={groupName}
177	                onChange={(e) => setGroupName(e.target.value)}
178	                placeholder="e.g. SaaS Competitors Q2"
179	                disabled={isPending}
180	              />
181	              {errors["name"] && (
182	                <p className="text-xs text-red-500">{errors["name"]}</p>
183	              )}
184	            </div>
185	
186	            {/* Primary URL */}
187	            <div className="space-y-1.5">
188	              <Label htmlFor="primary-url">Your website URL</Label>
189	              <Input
190	                id="primary-url"
191	                type="url"
192	                value={primaryUrl}
193	                onChange={(e) => {
194	                  setPrimaryUrl(e.target.value);
195	                  if (errors["primary"]) setErrors((p) => { const n = { ...p }; delete n["primary"]; return n; });
196	                }}
197	                placeholder="https://yoursite.com"
198	                disabled={isPending}
199	              />
200	              {errors["primary"] && (
201	                <p className="text-xs text-red-500">{errors["primary"]}</p>
202	              )}
203	            </div>
204	
205	            {/* Competitor URLs */}
206	            <div className="space-y-2">
207	              <Label>Competitor URLs</Label>
208	              {competitorUrls.map((url, idx) => (
209	                <div key={idx} className="flex items-center gap-2">
210	                  <Input
211	                    type="url"
212	                    value={url}
213	                    onChange={(e) => updateCompetitor(idx, e.target.value)}
214	                    placeholder={`https://competitor${idx + 1}.com`}
215	                    disabled={isPending}
216	                    className={errors[`competitor_${idx}`] ? "border-red-400" : ""}
217	                  />
218	                  {competitorUrls.length > 1 && (
219	                    <Button
220	                      type="button"
221	                      variant="ghost"
222	                      size="sm"
223	                      className="h-9 w-9 p-0 shrink-0 text-muted-foreground hover:text-red-500"
224	                      onClick={() => removeCompetitor(idx)}
225	                      disabled={isPending}
226	                      aria-label={`Remove competitor ${idx + 1}`}
227	                    >
228	                      <Trash2 className="h-4 w-4" />
229	                    </Button>
230	                  )}
231	                </div>
232	              ))}
233	              {competitorUrls.map((_, idx) =>
234	                errors[`competitor_${idx}`] ? (
235	                  <p key={idx} className="text-xs text-red-500">
236	                    Competitor {idx + 1}: {errors[`competitor_${idx}`]}
237	                  </p>
238	                ) : null
239	              )}
240	              {competitorUrls.length < MAX_COMPETITORS && (
241	                <Button
242	                  type="button"
243	                  variant="outline"
244	                  size="sm"
245	                  onClick={addCompetitor}
246	                  disabled={isPending}
247	                  className="mt-1"
248	                >
249	                  <Plus className="mr-1.5 h-3.5 w-3.5" />
250	                  Add another
251	                </Button>
252	              )}
253	            </div>
254	          </div>
255	
256	          <DialogFooter className="mt-6">
257	            <Button
258	              type="button"
259	              variant="outline"
260	              onClick={() => setOpen(false)}
261	              disabled={isPending}
262	            >
263	              Cancel
264	            </Button>
265	            <Button type="submit" disabled={isPending}>
266	              {isPending ? (
267	                <>
268	                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
269	                  Creating...
270	                </>
271	              ) : (
272	                <>
273	                  <Swords className="mr-2 h-4 w-4" />
274	                  Create & Scan All
275	                </>
276	              )}
277	            </Button>
278	          </DialogFooter>
279	        </form>
280	      </DialogContent>
281	    </Dialog>
282	  );
283	}
