1	import {
2	  Radar,
3	  RadarChart,
4	  PolarGrid,
5	  PolarAngleAxis,
6	  PolarRadiusAxis,
7	  Tooltip,
8	  Legend,
9	  ResponsiveContainer,
10	} from "recharts";
11	import type { CroPillar } from "@/types";
12	import { CRO_PILLARS } from "@/lib/constants";
13	
14	// ── Chart colors — one per series ──────────────────────────────
15	const SERIES_COLORS = [
16	  "hsl(var(--primary))",
17	  "#f59e0b",
18	  "#10b981",
19	  "#ef4444",
20	  "#8b5cf6",
21	] as const;
22	
23	// ── Types ───────────────────────────────────────────────────────
24	
25	export interface RadarSeriesItem {
26	  name: string;
27	  scores: Partial<Record<CroPillar, number>>;
28	}
29	
30	interface CompetitorRadarChartProps {
31	  data: RadarSeriesItem[];
32	}
33	
34	// ── Recharts data shape ─────────────────────────────────────────
35	
36	interface RadarDataPoint {
37	  pillar: string;
38	  fullMark: number;
39	  [key: string]: string | number;
40	}
41	
42	function buildChartData(data: RadarSeriesItem[]): RadarDataPoint[] {
43	  return CRO_PILLARS.map((pillar) => {
44	    const point: RadarDataPoint = {
45	      pillar: pillar.label,
46	      fullMark: 100,
47	    };
48	    data.forEach((series) => {
49	      point[series.name] = series.scores[pillar.key] ?? 0;
50	    });
51	    return point;
52	  });
53	}
54	
55	// ── Custom tooltip ───────────────────────────────────────────────
56	
57	interface TooltipPayloadEntry {
58	  name: string;
59	  value: number;
60	  color: string;
61	}
62	
63	interface CustomTooltipProps {
64	  active?: boolean;
65	  payload?: TooltipPayloadEntry[];
66	  label?: string;
67	}
68	
69	function CustomTooltip({ active, payload, label }: CustomTooltipProps) {
70	  if (!active || !payload?.length) return null;
71	
72	  return (
73	    <div className="rounded-lg border border-border/50 bg-popover px-3 py-2 shadow-md text-sm">
74	      <p className="mb-1.5 font-medium text-foreground">{label}</p>
75	      {payload.map((entry) => (
76	        <div key={entry.name} className="flex items-center gap-2">
77	          <span
78	            className="inline-block h-2 w-2 rounded-full shrink-0"
79	            style={{ background: entry.color }}
80	          />
81	          <span className="text-muted-foreground">{entry.name}:</span>
82	          <span className="font-medium tabular-nums text-foreground">{entry.value}</span>
83	        </div>
84	      ))}
85	    </div>
86	  );
87	}
88	
89	// ── Component ────────────────────────────────────────────────────
90	
91	export function CompetitorRadarChart({ data }: CompetitorRadarChartProps) {
92	  const chartData = buildChartData(data);
93	
94	  return (
95	    <div role="img" aria-label="Competitor comparison radar chart showing CRO scores across 7 pillars">
96	    <ResponsiveContainer width="100%" height={300}>
97	      <RadarChart data={chartData} margin={{ top: 10, right: 20, bottom: 10, left: 20 }}>
98	        <PolarGrid
99	          stroke="hsl(var(--border))"
100	          strokeOpacity={0.5}
101	        />
102	        <PolarAngleAxis
103	          dataKey="pillar"
104	          tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
105	          tickLine={false}
106	        />
107	        <PolarRadiusAxis
108	          angle={90}
109	          domain={[0, 100]}
110	          tick={{ fontSize: 10, fill: "hsl(var(--muted-foreground))" }}
111	          tickCount={5}
112	          stroke="hsl(var(--border))"
113	          strokeOpacity={0.3}
114	        />
115	        {data.map((series, index) => (
116	          <Radar
117	            key={series.name}
118	            name={series.name}
119	            dataKey={series.name}
120	            stroke={SERIES_COLORS[index % SERIES_COLORS.length]}
121	            fill={SERIES_COLORS[index % SERIES_COLORS.length]}
122	            fillOpacity={0.08}
123	            strokeWidth={2}
124	            dot={{ r: 3, fill: SERIES_COLORS[index % SERIES_COLORS.length] }}
125	          />
126	        ))}
127	        <Tooltip content={<CustomTooltip />} />
128	        <Legend
129	          wrapperStyle={{ fontSize: 12, paddingTop: 12 }}
130	          formatter={(value: string) => (
131	            <span style={{ color: "hsl(var(--muted-foreground))" }}>{value}</span>
132	          )}
133	        />
134	      </RadarChart>
135	    </ResponsiveContainer>
136	    </div>
137	  );
138	}
