1	import {
2	  Table,
3	  TableBody,
4	  TableCell,
5	  TableHead,
6	  TableHeader,
7	  TableRow,
8	} from "@/components/ui/table";
9	import { Badge } from "@/components/ui/badge";
10	import { cn } from "@/lib/utils";
11	import { CRO_PILLARS } from "@/lib/constants";
12	import type { CroPillar } from "@/types";
13	
14	// ── Types ───────────────────────────────────────────────────────
15	
16	export interface CompetitorScoreEntry {
17	  url: string;
18	  scores: Partial<Record<CroPillar, number>> | null;
19	  overallScore: number | null;
20	}
21	
22	interface CompetitorScoreTableProps {
23	  primaryUrl: string;
24	  competitors: CompetitorScoreEntry[];
25	}
26	
27	// ── Helpers ─────────────────────────────────────────────────────
28	
29	function tryHostname(url: string): string {
30	  try {
31	    return new URL(url).hostname.replace("www.", "");
32	  } catch {
33	    return url;
34	  }
35	}
36	
37	function scoreColor(score: number | null | undefined, isHighest: boolean, isLowest: boolean): string {
38	  if (score === null || score === undefined) return "text-muted-foreground";
39	  if (isHighest) return "text-emerald-600 font-semibold";
40	  if (isLowest) return "text-red-500 font-semibold";
41	  return "text-foreground";
42	}
43	
44	function scoreBg(isHighest: boolean, isLowest: boolean): string {
45	  if (isHighest) return "bg-emerald-50/60";
46	  if (isLowest) return "bg-red-50/40";
47	  return "";
48	}
49	
50	// ── Component ────────────────────────────────────────────────────
51	
52	export function CompetitorScoreTable({ primaryUrl, competitors }: CompetitorScoreTableProps) {
53	  // All columns: primary first, then competitors
54	  const allEntries: CompetitorScoreEntry[] = competitors;
55	
56	  return (
57	    <div className="overflow-x-auto scrollbar-thin rounded-lg border border-border/40">
58	      <Table>
59	        <TableHeader>
60	          <TableRow className="bg-muted/20 hover:bg-muted/20">
61	            <TableHead className="pl-4 min-w-[160px] font-semibold text-foreground">Pillar</TableHead>
62	            {/* Primary */}
63	            <TableHead className="text-center min-w-[120px]">
64	              <div className="flex flex-col items-center gap-0.5">
65	                <span className="text-xs text-muted-foreground">Your site</span>
66	                <span className="text-xs font-medium truncate max-w-[100px]" title={primaryUrl}>
67	                  {tryHostname(primaryUrl)}
68	                </span>
69	              </div>
70	            </TableHead>
71	            {/* Competitors (skip first entry which is primary) */}
72	            {allEntries.slice(1).map((entry) => (
73	              <TableHead key={entry.url} className="text-center min-w-[120px]">
74	                <div className="flex flex-col items-center gap-0.5">
75	                  <span className="text-xs text-muted-foreground">Competitor</span>
76	                  <span className="text-xs font-medium truncate max-w-[100px]" title={entry.url}>
77	                    {tryHostname(entry.url)}
78	                  </span>
79	                </div>
80	              </TableHead>
81	            ))}
82	          </TableRow>
83	        </TableHeader>
84	        <TableBody>
85	          {/* Per-pillar rows */}
86	          {CRO_PILLARS.map((pillar) => {
87	            const rowScores = allEntries.map((entry) =>
88	              entry.scores?.[pillar.key] ?? null
89	            );
90	            const validScores = rowScores.filter((s): s is number => s !== null);
91	            const maxScore = validScores.length ? Math.max(...validScores) : null;
92	            const minScore = validScores.length > 1 ? Math.min(...validScores) : null;
93	
94	            return (
95	              <TableRow key={pillar.key} className="hover:bg-muted/10">
96	                <TableCell className="pl-4">
97	                  <div className="flex items-center gap-2">
98	                    <pillar.icon className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
99	                    <span className="text-sm font-medium text-foreground">{pillar.label}</span>
100	                  </div>
101	                </TableCell>
102	                {rowScores.map((score, idx) => {
103	                  const isHighest = score !== null && score === maxScore;
104	                  const isLowest = score !== null && score === minScore && minScore !== maxScore;
105	                  return (
106	                    <TableCell
107	                      key={allEntries[idx]?.url ?? idx}
108	                      className={cn("text-center", scoreBg(isHighest, isLowest))}
109	                    >
110	                      {score !== null ? (
111	                        <div className="flex items-center justify-center gap-1.5">
112	                          <span className={cn("text-sm tabular-nums", scoreColor(score, isHighest, isLowest))}>
113	                            {score}
114	                          </span>
115	                          {isHighest && (
116	                            <Badge
117	                              variant="outline"
118	                              className="text-2xs border-emerald-200 bg-emerald-50 text-emerald-700 px-1 py-0 h-4"
119	                            >
120	                              Best
121	                            </Badge>
122	                          )}
123	                        </div>
124	                      ) : (
125	                        <span className="text-xs text-muted-foreground">--</span>
126	                      )}
127	                    </TableCell>
128	                  );
129	                })}
130	              </TableRow>
131	            );
132	          })}
133	
134	          {/* Overall score row */}
135	          {(() => {
136	            const overallScores = allEntries.map((e) => e.overallScore);
137	            const validOverall = overallScores.filter((s): s is number => s !== null);
138	            const maxOverall = validOverall.length ? Math.max(...validOverall) : null;
139	            const minOverall = validOverall.length > 1 ? Math.min(...validOverall) : null;
140	
141	            return (
142	              <TableRow className="bg-muted/10 font-medium border-t-2 border-border/50">
143	                <TableCell className="pl-4 font-semibold text-foreground">
144	                  Overall Score
145	                </TableCell>
146	                {overallScores.map((score, idx) => {
147	                  const isHighest = score !== null && score === maxOverall;
148	                  const isLowest = score !== null && score === minOverall && minOverall !== maxOverall;
149	                  return (
150	                    <TableCell
151	                      key={allEntries[idx]?.url ?? idx}
152	                      className={cn("text-center", scoreBg(isHighest, isLowest))}
153	                    >
154	                      {score !== null ? (
155	                        <div className="flex items-center justify-center gap-1.5">
156	                          <span className={cn("text-base font-bold tabular-nums", scoreColor(score, isHighest, isLowest))}>
157	                            {score}
158	                          </span>
159	                          {isHighest && (
160	                            <Badge
161	                              variant="outline"
162	                              className="text-2xs border-emerald-200 bg-emerald-50 text-emerald-700 px-1 py-0 h-4"
163	                            >
164	                              Winner
165	                            </Badge>
166	                          )}
167	                        </div>
168	                      ) : (
169	                        <span className="text-xs text-muted-foreground">--</span>
170	                      )}
171	                    </TableCell>
172	                  );
173	                })}
174	              </TableRow>
175	            );
176	          })()}
177	        </TableBody>
178	      </Table>
179	    </div>
180	  );
181	}
