// Brand color constant — CSS variables don't resolve in SVG/Recharts context
const BRAND_PRIMARY = "#5B5FC7";
const GRAY_PREVIOUS = "#CBD5E1";

import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  LabelList,
  Cell,
} from "recharts";
