30	import { useFeatureFlag } from "@/hooks/use-feature-flag";
31	import { BulkScanDialog } from "@/components/scan/BulkScanDialog";
32	import { toast } from "sonner";
33	import type { PageType } from "@/types";
34	import { isGrowthPlus } from "@/types";
35	import { cn } from "@/lib/utils";
36	
37	/** Generate a stable teaser score 45–72 for an unauthenticated guest scan */
38	function generateTeaserScore(url: string): number {
39	  let hash = 0;
40	  for (let i = 0; i < url.length; i++) {
41	    hash = (hash * 31 + url.charCodeAt(i)) & 0xffffffff;
42	  }
43	  return 45 + (Math.abs(hash) % 28);
44	}
45	
46	/** Basic URL validation — checks structure, not reachability */
47	function isValidUrl(str: string): boolean {
48	  try {
49	    const url = new URL(str.startsWith("http") ? str : `https://${str}`);
50	    return url.protocol === "https:" || url.protocol === "http:";
51	  } catch {
52	    return false;
53	  }
54	}
55	
56	/** Normalize URL: prepend https:// if missing */
57	function normalizeUrl(str: string): string {
58	  const trimmed = str.trim();
59	  if (!trimmed) return trimmed;
60	  if (/^https?:\/\//i.test(trimmed)) return trimmed;
61	  return `https://${trimmed}`;
62	}
63	
64	// ── Map scan status to step index ───────────────────────────────
65	
66	function statusToStep(status: string): number {
67	  switch (status) {
68	    case "pending": return 0;
69	    case "analyzing": return 3;
70	    case "completed": return SCAN_STEPS.length;
71	    case "failed": return -1;
72	    default: return 0;
73	  }
74	}
75	
76	const Scan = () => {
77	  const navigate = useNavigate();
78	  const [searchParams] = useSearchParams();
79	  const [rawUrl, setRawUrl] = useState(searchParams.get("url") || "");
80	  const [pageType, setPageType] = useState<PageType>(
81	    (searchParams.get("type") as PageType) || "landing"
82	  );
83	  const [urlError, setUrlError] = useState<string | null>(null);
84	
85	  // activeScanId drives the polling query (authenticated users only)
86	  const [activeScanId, setActiveScanId] = useState<string | null>(null);
87	  const [simulatedStep, setSimulatedStep] = useState(-1);
88	  const [scanFailed, setScanFailed] = useState(false);
89	
90	  // Guest flow: simulate the animation then show gate wall
91	  const [guestAnimating, setGuestAnimating] = useState(false);
92	  const [guestAnimationDone, setGuestAnimationDone] = useState(false);
93	  const [guestTeaserScore, setGuestTeaserScore] = useState(0);
94	
95	  const [bulkDialogOpen, setBulkDialogOpen] = useState(false);
96	
97	  const inputId = useId();
98	  const urlErrorId = useId();
99	  const { user, profile } = useAuth();
100	  const isAuthenticated = !!user;
101	  const freeScanEnabled = useFeatureFlag("free_scan_enabled", true);
102	  const createScan = useCreateScan();
103	
104	  const canUseBulk = isAuthenticated && isGrowthPlus(profile?.plan ?? "free");
105	
106	  const scansUsed = profile?.scans_used ?? 0;
107	  const scanLimit = profile?.scan_limit ?? 3;
108	  const scansRemaining = scanLimit - scansUsed;
109	  const atLimit = scansRemaining <= 0;
110	
111	  // Poll the scan row while it's pending/analyzing
112	  const { data: pollingScan } = useScan(activeScanId ?? undefined, {
113	    refetchInterval: activeScanId ? 2000 : false,
114	  });
115	
116	  const isAnalyzing = activeScanId !== null || guestAnimating;
117	  const normalizedUrl = normalizeUrl(rawUrl);
118	
119	  const totalSteps = SCAN_STEPS.length;
120	  const currentStep = isAnalyzing
121	    ? pollingScan
122	      ? statusToStep(pollingScan.status)
123	      : simulatedStep
124	    : -1;
125	  const progressPercent = currentStep < 0 ? 0 : Math.round(((currentStep + 1) / totalSteps) * 100);
126	
127	  // When polling finds a completed/failed scan, navigate or show error
128	  useEffect(() => {
129	    if (!pollingScan) return;
130	    if (pollingScan.status === "completed") {
131	      setTimeout(() => navigate(`/reports/${pollingScan.id}`), 600);
132	    } else if (pollingScan.status === "failed") {
133	      setActiveScanId(null);
134	      setSimulatedStep(-1);
135	      setScanFailed(true);
136	    }
137	    // eslint-disable-next-line react-hooks/exhaustive-deps
138	  }, [pollingScan?.status]);
139	
140	  // Simulate step progression while waiting for the edge function (authenticated)
141	  useEffect(() => {
142	    if (!isAnalyzing || !activeScanId) return;
143	    if (pollingScan?.status === "completed" || pollingScan?.status === "failed") return;
144	    if (simulatedStep >= totalSteps - 1) return;
145	
146	    const durations = [900, 1400, 1200, 1100, 1300, 1000, 1600];
147	    const timer = setTimeout(
148	      () => setSimulatedStep((prev) => prev + 1),
149	      durations[simulatedStep] ?? 1200
150	    );
151	    return () => clearTimeout(timer);
152	    // totalSteps is derived from a constant — safe to omit
153	    // eslint-disable-next-line react-hooks/exhaustive-deps
154	  }, [isAnalyzing, activeScanId, simulatedStep, pollingScan?.status]);
155	
156	  // Guest simulated step progression — no API call, just animation
157	  useEffect(() => {
158	    if (!guestAnimating || guestAnimationDone) return;
159	    if (simulatedStep >= totalSteps - 1) {
160	      // Animation finished — show gate wall
161	      const timer = setTimeout(() => {
162	        setGuestAnimationDone(true);
163	        setGuestAnimating(false);
164	      }, 800);
165	      return () => clearTimeout(timer);
166	    }
167	
168	    const durations = [900, 1400, 1200, 1100, 1300, 1000, 1600];
169	    const timer = setTimeout(
170	      () => setSimulatedStep((prev) => prev + 1),
171	      durations[simulatedStep] ?? 1200
172	    );
173	    return () => clearTimeout(timer);
174	    // eslint-disable-next-line react-hooks/exhaustive-deps
175	  }, [guestAnimating, guestAnimationDone, simulatedStep]);
176	
177	  const startAnalysis = useCallback(() => {
178	    setUrlError(null);
179	    if (!rawUrl.trim()) {
180	      setUrlError("Please enter a URL.");
181	      return;
182	    }
183	    if (!isValidUrl(normalizedUrl)) {
184	      setUrlError("Enter a valid URL like https://example.com/page");
185	      return;
186	    }
187	
188	    // Unauthenticated users: if free scan disabled, redirect to signup immediately
189	    if (!isAuthenticated) {
190	      if (!freeScanEnabled) {
191	        navigate("/signup");
192	        return;
193	      }
194	      setGuestAnimating(true);
195	      setGuestAnimationDone(false);
196	      setGuestTeaserScore(generateTeaserScore(normalizedUrl));
197	      setSimulatedStep(0);
198	      return;
199	    }
200	
201	    if (atLimit) return;
202	
203	    setSimulatedStep(0);
204	
205	    createScan.mutate(
206	      { url: normalizedUrl, page_type: pageType },
207	      {
208	        onSuccess: (scan) => {
209	          setActiveScanId(scan.id);
210	        },
211	        onError: (err: unknown) => {
212	          setSimulatedStep(-1);
213	          const message = err instanceof Error ? err.message : "Failed to start scan";
214	          toast.error(message);
215	        },
216	      }
217	    );
218	  }, [rawUrl, normalizedUrl, pageType, isAuthenticated, atLimit, createScan]);
219	
220	  const handleSubmit = (e: React.FormEvent) => {
221	    e.preventDefault();
222	    startAnalysis();
223	  };
224	
225	  // ── Guest Gate Wall ─────────────────────────────────────────
226	  if (guestAnimationDone) {
227	    return (
228	      <PageTransition>
229	        <ScanGateWall teaserScore={guestTeaserScore} url={normalizedUrl} />
230	      </PageTransition>
231	    );
232	  }
233	
234	  // ── Analysis Progress View ──────────────────────────────────
235	  if (isAnalyzing) {
236	    let hostname = rawUrl;
237	    try { hostname = new URL(normalizedUrl).hostname; } catch { /* keep raw */ }
238	
239	    const displayStep = Math.max(0, currentStep);
240	
241	    return (
242	      <PageTransition>
243	        <div className="mx-auto max-w-2xl space-y-6">
244	          <div>
245	            <h2 className="text-2xl font-bold tracking-tight text-foreground">Analyzing your page</h2>
246	            <p className="mt-1 text-sm text-muted-foreground">
247	              Scanning <span className="font-medium text-foreground">{hostname}</span> — this usually takes 20-40 seconds
248	            </p>
249	          </div>
250	
251	          {/* Progress bar */}
252	          <div className="space-y-1.5">
253	            <div className="flex items-center justify-between text-sm">
254	              <span className="text-muted-foreground">
255	                Step {Math.min(displayStep + 1, totalSteps)} of {totalSteps}
256	              </span>
257	              <span className="tabular-nums font-medium text-foreground">{Math.min(progressPercent, 100)}%</span>
258	            </div>
259	            <Progress value={Math.min(progressPercent, 100)} className="h-2" />
260	          </div>
261	
262	          {/* Browser frame */}
263	          <BrowserFrame url={normalizedUrl}>
264	            <div className="relative flex h-52 items-center justify-center bg-gradient-to-br from-slate-50 via-white to-slate-50">
265	              {/* Scanning animation */}
266	              <div className="absolute inset-x-0 top-0 h-1 overflow-hidden">
267	                <div className="h-full w-1/3 animate-[shimmer_1.5s_ease-in-out_infinite] bg-gradient-to-r from-transparent via-primary/30 to-transparent" />
268	              </div>
269	              <div className="text-center">
270	                <Loader2 className="mx-auto mb-3 h-8 w-8 animate-spin text-primary" />
271	                <p className="text-sm font-medium text-muted-foreground">
272	                  {displayStep < totalSteps ? SCAN_STEPS[displayStep]?.label : "Finalizing report"}...
273	                </p>
274	              </div>
275	            </div>
276	          </BrowserFrame>
277	
278	          {/* Timeline */}
279	          <Card className="border-border/50 shadow-soft">
280	            <CardContent className="p-6">
281	              <ScanProgressTimeline steps={SCAN_STEPS} currentStep={displayStep} />
282	            </CardContent>
283	          </Card>
284	        </div>
285	      </PageTransition>
286	    );
287	  }
288	
289	  // ── URL Input Form ──────────────────────────────────────────
290	  return (
291	    <PageTransition>
292	      <div className="mx-auto max-w-2xl space-y-8">
293	        <div className="text-center">
294	          <h2 className="text-2xl font-bold tracking-tight text-foreground">Analyze your page</h2>
295	          <p className="mt-2 text-muted-foreground">
296	            Enter any URL to get a detailed CRO audit with actionable recommendations
297	          </p>
298	        </div>
299	
300	        {/* URL Input Card */}
301	        <Card className="border-border/50 shadow-soft">
302	          <CardContent className="p-8">
303	            <form onSubmit={handleSubmit} className="space-y-4">
304	              <div>
305	                <label htmlFor={inputId} className="mb-1.5 block text-sm font-medium text-foreground">
306	                  Page URL
307	                </label>
308	                <div className="relative">
309	                  <Globe className="absolute left-4 top-1/2 h-4.5 w-4.5 -translate-y-1/2 text-muted-foreground" />
310	                  <Input
311	                    id={inputId}
312	                    type="text"
313	                    placeholder="example.com/landing-page"
314	                    value={rawUrl}
315	                    onChange={(e) => { setRawUrl(e.target.value); setUrlError(null); }}
316	                    aria-invalid={urlError ? true : undefined}
317	                    aria-describedby={urlError ? urlErrorId : undefined}
318	                    className={cn(
319	                      "h-14 rounded-xl border-border/50 bg-card pl-11 pr-5 text-base placeholder:text-muted-foreground focus-visible:border-primary focus-visible:ring-primary/20",
320	                      urlError && "border-red-300 focus-visible:border-red-400 focus-visible:ring-red-400/20"
321	                    )}
322	                  />
323	                </div>
324	                {urlError && (
325	                  <p id={urlErrorId} role="alert" className="mt-1.5 flex items-center gap-1 text-sm text-red-600">
326	                    <AlertCircle className="h-3.5 w-3.5" aria-hidden="true" />
327	                    {urlError}
328	                  </p>
329	                )}
330	              </div>
331	
332	              <div>
333	                <label className="mb-1.5 block text-sm font-medium text-foreground">Page type</label>
334	                <Select value={pageType} onValueChange={(v) => setPageType(v as PageType)}>
335	                  <SelectTrigger className="h-12 rounded-xl border-border/50 bg-card">
336	                    <SelectValue placeholder="Select page type" />
337	                  </SelectTrigger>
338	                  <SelectContent>
339	                    {PAGE_TYPES.map((type) => (
340	                      <SelectItem key={type.value} value={type.value}>
341	                        {type.label}
342	                      </SelectItem>
343	                    ))}
344	                  </SelectContent>
345	                </Select>
346	                <p className="mt-1 text-xs text-muted-foreground">
347	                  Page type affects how we weight each CRO pillar in the overall score
348	                </p>
