350	
351	              <Button
352	                type="submit"
353	                className="h-14 w-full rounded-xl text-base font-semibold"
354	                disabled={!rawUrl.trim() || (isAuthenticated && (atLimit || createScan.isPending)) || guestAnimating}
355	              >
356	                {isAuthenticated && atLimit ? (
357	                  "Scan limit reached — Upgrade to continue"
358	                ) : isAuthenticated && createScan.isPending ? (
359	                  <>
360	                    <Loader2 className="mr-2 h-5 w-5 animate-spin" />
361	                    Starting scan...
362	                  </>
363	                ) : !isAuthenticated ? (
364	                  <>
365	                    <ScanLine className="mr-2 h-5 w-5" />
366	                    Analyze Free — No Sign Up Needed
367	                  </>
368	                ) : (
369	                  <>
370	                    <ScanLine className="mr-2 h-5 w-5" />
371	                    Start Analysis
372	                  </>
373	                )}
374	              </Button>
375	            </form>
376	
377	            {/* Bulk scan entry point */}
378	            {isAuthenticated && (
379	              <div className="mt-3 flex items-center justify-center gap-2">
380	                {canUseBulk ? (
