138	function CopyButton({ text }: { text: string }) {
139	  const [copied, setCopied] = useState(false);
140	  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
141	
142	  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); }, []);
143	
144	  const handleCopy = async () => {
145	    if (timerRef.current) clearTimeout(timerRef.current);
146	    try {
147	      await navigator.clipboard.writeText(text);
148	    } catch {
149	      const textarea = document.createElement("textarea");
150	      textarea.value = text;
151	      document.body.appendChild(textarea);
152	      textarea.select();
153	      document.execCommand("copy");
154	      document.body.removeChild(textarea);
155	    }
156	    setCopied(true);
157	    timerRef.current = setTimeout(() => setCopied(false), 2000);
158	  };
159	
160	  return (
161	    <TooltipProvider delayDuration={200}>
162	      <Tooltip>
163	        <TooltipTrigger asChild>
164	          <button
165	            onClick={handleCopy}
166	            className={cn(
167	              "inline-flex items-center gap-1 rounded-md px-2 py-1 text-xs font-medium transition-all",
168	              copied
169	                ? "bg-green-50 text-green-600 border border-green-200"
170	                : "bg-card/80 text-slate-500 border border-border/50 hover:bg-muted/40 hover:text-foreground"
171	            )}
172	          >
173	            {copied ? (
174	              <><Check className="h-3 w-3" />Copied</>
175	            ) : (
176	              <><Copy className="h-3 w-3" />Copy</>
177	            )}
178	          </button>
179	        </TooltipTrigger>
180	        <TooltipContent side="top">
181	          <p>{copied ? "Copied to clipboard!" : "Copy AI suggestion"}</p>
182	        </TooltipContent>
183	      </Tooltip>
184	    </TooltipProvider>
185	  );
186	}
