397	          <p className="mt-2 max-w-sm text-sm text-muted-foreground">
398	            This scan may have been deleted or hasn't finished processing yet.
399	          </p>
400	          <div className="mt-6 flex gap-3">
401	            <Button variant="outline" asChild>
402	              <Link to="/reports">View All Reports</Link>
403	            </Button>
404	            <Button asChild>
