466	        <div className="flex items-center gap-2 text-sm text-muted-foreground">
467	          <Button variant="ghost" size="sm" asChild className="text-muted-foreground -ml-2 h-auto p-1">
468	            <Link to="/reports">
469	              <ArrowLeft className="mr-1 h-3.5 w-3.5" />
470	              Reports
471	            </Link>
472	          </Button>
473	          <span className="text-muted-foreground/40">/</span>
474	          <span className="truncate text-slate-500">
475	            {scan.page_title ?? scan.url}
476	          </span>
