531	                onClick={() => {
532	                  if (!scan || pillarResults.length === 0) {
533	                    toast.error("Report data not ready yet. Please wait.");
534	                    return;
535	                  }
536	                  setPdfDialogOpen(true);
537	                }}
538	              >
539	                <Download className="mr-1.5 h-3.5 w-3.5" />
540	                PDF Report
541	              </Button>
542	            ) : (
