544	                variant="outline"
545	                className="border-border/50 text-muted-foreground text-xs px-3 py-1.5 h-9 flex items-center gap-1.5 cursor-not-allowed"
546	                title="PDF export is currently disabled"
547	              >
548	                <Download className="h-3.5 w-3.5" />
