554	                <Button variant="outline" size="sm" className="border-border/50">
555	                  <Share2 className="mr-1.5 h-3.5 w-3.5" />
556	                  Share
557	                </Button>
558	              </DropdownMenuTrigger>
559	              <DropdownMenuContent align="end" className="w-60">
560	                {/* Public share link — generate or copy */}
561	                <DropdownMenuItem
562	                  disabled={generateShareLink.isPending}
563	                  onClick={async () => {
564	                    try {
565	                      let shareUrl: string;
566	                      if (scan.share_token) {
567	                        shareUrl = `${window.location.origin}/r/${scan.share_token}`;
568	                      } else {
569	                        shareUrl = await generateShareLink.mutateAsync(scan.id);
