                    <Share2 className="mr-2 h-4 w-4" />
                  )}
                  {linkCopied ? "Link copied!" : scan.share_token ? "Copy public link" : "Generate public link"}
                </DropdownMenuItem>
                {scan.is_public && scan.share_token && (
