                ))}
                {CRO_PILLARS.filter(
                  (p) => !pillarResults.some((r) => r.pillar === p.key)
                ).map((pillar) => (
                  <PillarBarWithBenchmark
                    key={pillar.key}
                    pillar={pillar.key}
                    score={0}
