                ))}
              </div>
            </div>
          </CardContent>
        </Card>

        {/* ── Industry Benchmark Comparison ───────────────────── */}
        {pillarResults.length > 0 && (
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <h3 className="text-sm font-semibold text-muted-foreground uppercase tracking-wider">
                Benchmark vs. Industry
              </h3>
              <Select
                value={selectedIndustry}
                onValueChange={(v) => setSelectedIndustry(v as IndustryType)}
              >
                <SelectTrigger className="h-8 w-44 text-xs border-border/50">
                  <SelectValue placeholder="Select industry" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="saas">SaaS</SelectItem>
                  <SelectItem value="ecommerce">E-commerce</SelectItem>
                  <SelectItem value="agency">Agency</SelectItem>
                  <SelectItem value="finance">Finance</SelectItem>
                  <SelectItem value="healthcare">Healthcare</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <BenchmarkComparison
              pillarResults={pillarResults}
              benchmarks={industryBenchmarks}
            />
          </div>
        )}

        {/* ── GA4 Analytics Correlation ───────────────────────── */}
        {ga4Connected && profile && (
          <AnalyticsCorrelation url={scan.url} />
        )}

        {/* ── Score History Chart ─────────────────────────────── */}
        {historyChartData.length >= 2 && (
          <Card className="border-border/50 shadow-none">
            <CardHeader className="pb-2">
              <CardTitle className="flex items-center gap-2 text-base font-semibold">
                <TrendingUp className="h-4 w-4 text-primary" />
                Score History
              </CardTitle>
              <p className="text-xs text-muted-foreground">
                How this URL&apos;s CRO score has changed over time
              </p>
            </CardHeader>
            <CardContent className="pb-4">
              <ScoreHistoryChart data={historyChartData} height={180} />
            </CardContent>
          </Card>
        )}

        {/* ── Annotated Mockup + Key Issues Sidebar ───────────── */}
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-5">
          {/* Annotated Browser Mockup */}
          <div className="lg:col-span-3">
            <BrowserFrame url={scan.url}>
              <div className="relative h-[300px] sm:h-[420px] overflow-hidden bg-gradient-to-br from-slate-50 via-white to-slate-50">
                <div className="absolute inset-0 p-4">
                  <div className="flex items-center justify-between px-3 py-2">
                    <div className="h-5 w-24 rounded bg-slate-200/80" />
                    <div className="flex gap-3">
                      <div className="h-3 w-12 rounded bg-slate-200/60" />
                      <div className="h-3 w-12 rounded bg-slate-200/60" />
                      <div className="h-3 w-12 rounded bg-slate-200/60" />
                      <div className="h-6 w-16 rounded-md bg-slate-200/80" />
                    </div>
                  </div>
                  <div className="mt-8 flex flex-col items-center px-6 text-center">
                    <div className="h-6 w-72 rounded bg-slate-200/80 mb-3" />
                    <div className="h-4 w-56 rounded bg-slate-200/50 mb-2" />
                    <div className="h-4 w-48 rounded bg-slate-200/40 mb-6" />
                    <div className="h-3 w-36 rounded bg-slate-200/30" />
