40	function getNextScanDate(entry: MonitoredUrl): string {
41	  if (!entry.last_scanned_at) return "Soon";
42	
43	  const last = new Date(entry.last_scanned_at);
44	  const next = new Date(last);
45	
46	  switch (entry.frequency) {
47	    case "daily":
48	      next.setDate(next.getDate() + 1);
49	      break;
50	    case "weekly":
51	      next.setDate(next.getDate() + 7);
52	      break;
53	    case "monthly":
54	      next.setDate(next.getDate() + 30);
55	      break;
56	  }
57	
58	  const now = new Date();
59	  if (next <= now) return "Due now";
60	
61	  return next.toLocaleDateString("en-US", { month: "short", day: "numeric" });
62	}
