64	function truncateUrl(url: string, maxLen = 42): string {
65	  try {
66	    const { hostname, pathname } = new URL(url);
67	    const display = hostname.replace("www.", "") + pathname;
68	    return display.length > maxLen ? display.slice(0, maxLen) + "…" : display;
69	  } catch {
70	    return url.length > maxLen ? url.slice(0, maxLen) + "…" : url;
71	  }
72	}
