775	      setSubjectError("Subject is required.");
776	      valid = false;
777	    } else if (subject.length > 100) {
778	      setSubjectError("Subject must be 100 characters or less.");
779	      valid = false;
780	    } else {
781	      setSubjectError(null);
782	    }
783	
784	    if (!message.trim()) {
785	      setMessageError("Message is required.");
786	      valid = false;
