789	      valid = false;
790	    } else if (message.length > 2000) {
791	      setMessageError("Message must be 2000 characters or less.");
792	      valid = false;
793	    } else {
794	      setMessageError(null);
795	    }
796	
797	    if (!valid) return;
798	
799	    submitRequest.mutate(
800	      { subject: subject.trim(), message: message.trim(), priority },
801	      {
802	        onSuccess: () => {
803	          setSubject("");
804	          setMessage("");
805	          setPriority("normal");
806	        },
807	      }
