34	function tryHostname(url: string): string {
35	  try {
36	    return new URL(url).hostname.replace("www.", "");
37	  } catch {
38	    return url;
39	  }
40	}
41	
42	function formatDate(dateStr: string | null): string {
43	  if (!dateStr) return "Not scanned";
44	  return new Date(dateStr).toLocaleDateString("en-US", {
45	    month: "short",
46	    day: "numeric",
47	  });
48	}
