52	function buildRadarData(group: CompetitorGroupWithUrls): RadarSeriesItem[] {
53	  return group.competitor_urls.map((cu) => {
54	    const scores: Partial<Record<CroPillar, number>> = {};
55	    // We don't have pillar scores in competitor_urls — only overall.
56	    // The radar shows overall-score-only placeholder until pillar data is available.
57	    // For now, distribute overall score as equal across all pillars if no pillar data.
58	    const fallback = cu.latest_score ?? 0;
59	    CRO_PILLARS.forEach((p) => {
60	      scores[p.key] = fallback;
61	    });
62	    return { name: tryHostname(cu.url), scores };
63	  });
64	}
65	
66	function buildTableData(group: CompetitorGroupWithUrls): CompetitorScoreEntry[] {
67	  return group.competitor_urls.map((cu) => ({
68	    url: cu.url,
69	    scores: null, // pillar scores require scan_results join — not in this table
70	    overallScore: cu.latest_score,
71	  }));
72	}
