'use client';

import { useRouter } from "next/navigation";
import { TrendingUp, TrendingDown, Minus, History, ScanLine } from "lucide-react";
import { motion } from "framer-motion";
import { Card, CardContent } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { Button } from "@/components/ui/button";
import { PageTransition } from "@/components/shared/PageTransition";
import { ScoreRing } from "@/components/shared/ScoreRing";
import { ScoreHistoryChart } from "@/components/audit/ScoreHistoryChart";
import { useAllUrlHistory } from "@/hooks/use-scan-history";
import type { UrlHistoryGroup } from "@/hooks/use-scan-history";
import { cn } from "@/lib/utils";

// ── URL truncation ────────────────────────────────────────────────

function truncateUrl(url: string, max = 48): string {
  try {
    const u = new URL(url);
    const display = u.hostname + u.pathname;
    return display.length > max ? display.slice(0, max) + "\u2026" : display;
  } catch {
    return url.length > max ? url.slice(0, max) + "\u2026" : url;
  }
}

// ── Delta Badge ───────────────────────────────────────────────────

function DeltaChip({ delta }: { delta: number }) {
  if (delta === 0) {
    return (
      <span className="inline-flex items-center gap-0.5 rounded-full bg-muted px-2 py-0.5 text-xs font-semibold text-muted-foreground">
        <Minus className="h-3 w-3" />
        No change
      </span>
    );
  }
  const isUp = delta > 0;
  return (
    <span
      className={cn(
        "inline-flex items-center gap-0.5 rounded-full px-2 py-0.5 text-xs font-bold",
        isUp ? "bg-green-100 text-green-700" : "bg-red-100 text-red-600"
      )}
    >
      {isUp ? <TrendingUp className="h-3 w-3" /> : <TrendingDown className="h-3 w-3" />}
      {isUp ? `+${delta}` : delta} pts
    </span>
  );
}

// ── URL History Card ──────────────────────────────────────────────

function UrlHistoryCard({ group, index }: { group: UrlHistoryGroup; index: number }) {
  const router = useRouter();

  const sparklineData = group.entries.map((e) => ({
    date: e.scanned_at,
    score: e.score,
  }));

  return (
    <motion.div
      initial={{ opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.3, ease: "easeOut", delay: index * 0.06 }}
    >
      <Card
        className="cursor-pointer border-border/40 shadow-soft transition-all duration-150 hover:border-primary/30 hover:shadow-md"
        onClick={() => router.push(`/reports/${group.latestScanId}`)}
        role="button"
        tabIndex={0}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            router.push(`/reports/${group.latestScanId}`);
          }
        }}
        aria-label={`View history for ${group.url}`}
      >
        <CardContent className="p-5">
          <div className="flex items-start gap-4">
            {/* Score ring */}
            <div className="shrink-0">
              <ScoreRing score={group.latestScore} size={56} strokeWidth={5} showLabel={false} />
            </div>

            {/* Main info */}
            <div className="min-w-0 flex-1">
              <div className="flex flex-wrap items-start justify-between gap-2">
                <div className="min-w-0">
                  <p className="truncate text-sm font-semibold text-foreground">
                    {truncateUrl(group.url)}
                  </p>
                  <p className="mt-0.5 text-xs text-muted-foreground">
                    {group.entries.length} scan{group.entries.length !== 1 ? "s" : ""}
                  </p>
                </div>
                <DeltaChip delta={group.delta} />
              </div>

              {/* Sparkline */}
              <div className="mt-3">
                <ScoreHistoryChart data={sparklineData} height={60} />
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    </motion.div>
  );
}

// ── Loading Skeleton ──────────────────────────────────────────────

function HistorySkeleton() {
  return (
    <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
      {[1, 2, 3, 4].map((i) => (
        <Skeleton key={i} className="h-40 w-full rounded-xl" />
      ))}
    </div>
  );
}

// ── Empty State ───────────────────────────────────────────────────

function HistoryEmptyState() {
  const router = useRouter();
  return (
    <div className="flex flex-col items-center justify-center py-24 text-center">
      <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-2xl bg-muted/50">
        <History className="h-8 w-8 text-muted-foreground" />
      </div>
      <h3 className="text-lg font-semibold text-foreground">No history yet</h3>
      <p className="mt-2 max-w-sm text-sm text-muted-foreground">
        You haven&apos;t scanned any URLs yet. Run your first scan to start tracking scores over time.
      </p>
      <Button className="mt-6" onClick={() => router.push("/scan")}>
        <ScanLine className="mr-2 h-4 w-4" />
        Run First Scan
      </Button>
    </div>
  );
}

// ── Page ──────────────────────────────────────────────────────────

export default function HistoryPage() {
  const { data: groups = [], isLoading } = useAllUrlHistory();

  return (
    <PageTransition>
      <div className="space-y-6">
        {/* Header */}
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-foreground sm:text-3xl">
            Score History
          </h1>
          <p className="mt-1 text-sm text-muted-foreground">
            Track how your CRO scores have changed over time for each URL.
          </p>
        </div>

        {/* Content */}
        {isLoading ? (
          <HistorySkeleton />
        ) : groups.length === 0 ? (
          <HistoryEmptyState />
        ) : (
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            {groups.map((group, i) => (
              <UrlHistoryCard key={group.url_hash} group={group} index={i} />
            ))}
          </div>
        )}
      </div>
    </PageTransition>
  );
}

'use client';

import { useState } from "react";
import Link from "next/link";
import { motion, AnimatePresence } from "framer-motion";
import { Activity, Plus, Trash2, Settings2, ExternalLink, Bell, CalendarClock, Lock, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { useAuth } from "@/contexts/AuthContext";
import { isProPlus } from "@/types/index";
import {
  useMonitoredUrls,
  useAddMonitoredUrl,
  useRemoveMonitoredUrl,
  useUpdateMonitoringSettings,
} from "@/hooks/use-monitoring";
import type { MonitoredUrl, MonitoringFrequency } from "@/types";
import { ScoreRing } from "@/components/shared/ScoreRing";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";

// ── Helpers ────────────────────────────────────────────────────

function getNextScanDate(entry: MonitoredUrl): string {
  if (!entry.last_scanned_at) return "Soon";

  const last = new Date(entry.last_scanned_at);
  const next = new Date(last);

  switch (entry.frequency) {
    case "daily":
      next.setDate(next.getDate() + 1);
      break;
    case "weekly":
      next.setDate(next.getDate() + 7);
      break;
    case "monthly":
      next.setDate(next.getDate() + 30);
      break;
  }

  const now = new Date();
  if (next <= now) return "Due now";

  return next.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

function truncateUrl(url: string, maxLen = 42): string {
  try {
    const { hostname, pathname } = new URL(url);
    const display = hostname.replace("www.", "") + pathname;
    return display.length > maxLen ? display.slice(0, maxLen) + "\u2026" : display;
  } catch {
    return url.length > maxLen ? url.slice(0, maxLen) + "\u2026" : url;
  }
}

const FREQUENCY_LABELS: Record<MonitoringFrequency, string> = {
  daily: "Daily",
  weekly: "Weekly",
  monthly: "Monthly",
};

// ── Plan gate ──────────────────────────────────────────────────

function PremiumLock() {
  return (
    <div className="flex flex-col items-center justify-center gap-4 py-20 text-center">
      <div className="flex h-14 w-14 items-center justify-center rounded-full bg-amber-100 dark:bg-amber-900/30">
        <Lock className="h-6 w-6 text-amber-600" />
      </div>
      <div>
        <h2 className="text-xl font-semibold">Pro Feature</h2>
        <p className="mt-1 text-sm text-muted-foreground max-w-sm">
          Automated score monitoring is available on Pro and Agency plans. Upgrade to start tracking your URLs.
        </p>
      </div>
      <Button asChild>
        <Link href="/pricing">Upgrade to Pro</Link>
      </Button>
    </div>
  );
}

// ── Empty state ────────────────────────────────────────────────

function EmptyMonitoringState({ onAdd }: { onAdd: () => void }) {
  return (
    <div className="flex flex-col items-center justify-center gap-4 py-20 text-center">
      <div className="flex h-14 w-14 items-center justify-center rounded-full bg-muted">
        <Activity className="h-6 w-6 text-muted-foreground" />
      </div>
      <div>
        <h2 className="text-xl font-semibold">No URLs monitored yet</h2>
        <p className="mt-1 text-sm text-muted-foreground max-w-sm">
          Add your first URL to start tracking CRO scores automatically. You&apos;ll get alerted when scores drop.
        </p>
      </div>
      <Button onClick={onAdd}>
        <Plus className="mr-2 h-4 w-4" />
        Monitor Your First URL
      </Button>
    </div>
  );
}

// ── Loading skeleton ───────────────────────────────────────────

function MonitoringCardSkeleton() {
  return (
    <Card>
      <CardContent className="p-5">
        <div className="flex items-start justify-between gap-4">
          <div className="flex items-center gap-3 min-w-0">
            <Skeleton className="h-10 w-10 rounded-full shrink-0" />
            <div className="space-y-1.5 min-w-0">
              <Skeleton className="h-4 w-48" />
              <Skeleton className="h-3 w-24" />
            </div>
          </div>
          <Skeleton className="h-6 w-16 shrink-0" />
        </div>
        <div className="mt-4 flex items-center gap-4">
          <Skeleton className="h-8 w-32" />
          <Skeleton className="h-8 w-24" />
        </div>
      </CardContent>
    </Card>
  );
}

// ── Monitored URL card ─────────────────────────────────────────

interface MonitoredUrlCardProps {
  entry: MonitoredUrl;
  onRemove: (id: string) => void;
  isRemoving: boolean;
}

function MonitoredUrlCard({ entry, onRemove, isRemoving }: MonitoredUrlCardProps) {
  const updateSettings = useUpdateMonitoringSettings();
  const [localFrequency, setLocalFrequency] = useState<MonitoringFrequency>(entry.frequency);
  const [localThreshold, setLocalThreshold] = useState(String(entry.alert_threshold));
  const [showSettings, setShowSettings] = useState(false);

  const handleToggleActive = (checked: boolean) => {
    updateSettings.mutate(
      { id: entry.id, is_active: checked },
      {
        onSuccess: () => toast.success(checked ? "Monitoring enabled" : "Monitoring paused"),
        onError: () => toast.error("Failed to update monitoring status"),
      }
    );
  };

  const handleSaveSettings = () => {
    const threshold = parseInt(localThreshold, 10);
    if (isNaN(threshold) || threshold < 1 || threshold > 20) {
      toast.error("Threshold must be between 1 and 20");
      return;
    }

    updateSettings.mutate(
      { id: entry.id, frequency: localFrequency, alert_threshold: threshold },
      {
        onSuccess: () => {
          toast.success("Settings updated");
          setShowSettings(false);
        },
        onError: () => toast.error("Failed to update settings"),
      }
    );
  };

  const nextScan = getNextScanDate(entry);

  return (
    <Card className="overflow-hidden">
      <CardContent className="p-5">
        <div className="flex items-start justify-between gap-4">
          {/* Left: score ring + URL info */}
          <div className="flex items-center gap-3 min-w-0">
            {entry.last_score !== null ? (
              <ScoreRing
                score={entry.last_score}
                size={40}
                strokeWidth={4}
                showLabel={false}
                className="shrink-0"
              />
            ) : (
              <div className="flex h-10 w-10 items-center justify-center rounded-full bg-muted shrink-0">
                <Activity className="h-4 w-4 text-muted-foreground" />
              </div>
            )}

            <div className="min-w-0">
              <div className="flex items-center gap-1.5">
                <p className="text-sm font-medium truncate">{truncateUrl(entry.url)}</p>
                <a
                  href={entry.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
                  aria-label="Open URL in new tab"
                >
                  <ExternalLink className="h-3.5 w-3.5" />
                </a>
              </div>
              <div className="mt-0.5 flex items-center gap-2 flex-wrap">
                <Badge variant="secondary" className="text-2xs px-1.5 py-0 h-4">
                  {FREQUENCY_LABELS[entry.frequency]}
                </Badge>
                <span className="text-xs text-muted-foreground flex items-center gap-1">
                  <CalendarClock className="h-3 w-3" />
                  Next: {nextScan}
                </span>
                {entry.last_score !== null && (
                  <span className="text-xs text-muted-foreground">
                    Score: {entry.last_score}
                  </span>
                )}
              </div>
            </div>
          </div>

          {/* Right: active toggle */}
          <div className="flex items-center gap-2 shrink-0">
            <Switch
              checked={entry.is_active}
              onCheckedChange={handleToggleActive}
              disabled={updateSettings.isPending}
              aria-label="Toggle monitoring active"
            />
          </div>
        </div>

        {/* Settings row */}
        <div className="mt-4 flex items-center gap-2 flex-wrap">
          <Button
            variant="outline"
            size="sm"
            onClick={() => setShowSettings(!showSettings)}
            className="h-8 text-xs"
          >
            <Settings2 className="mr-1.5 h-3.5 w-3.5" />
            Settings
          </Button>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => onRemove(entry.id)}
            disabled={isRemoving}
            className="h-8 text-xs text-destructive hover:text-destructive hover:bg-destructive/10"
            aria-label="Remove from monitoring"
          >
            {isRemoving ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Trash2 className="h-3.5 w-3.5" />
            )}
          </Button>
        </div>

        {/* Inline settings panel */}
        <AnimatePresence>
          {showSettings && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
              exit={{ opacity: 0, height: 0 }}
              transition={{ duration: 0.2 }}
              className="overflow-hidden"
            >
              <div className="mt-4 border-t border-border/60 pt-4 grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <Label className="text-xs text-muted-foreground">Frequency</Label>
                  <Select
                    value={localFrequency}
                    onValueChange={(v) => setLocalFrequency(v as MonitoringFrequency)}
                  >
                    <SelectTrigger className="h-8 text-xs">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="daily">Daily</SelectItem>
                      <SelectItem value="weekly">Weekly</SelectItem>
                      <SelectItem value="monthly">Monthly</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-1.5">
                  <Label className="text-xs text-muted-foreground">
                    Alert threshold (points)
                  </Label>
                  <Input
                    type="number"
                    min={1}
                    max={20}
                    value={localThreshold}
                    onChange={(e) => setLocalThreshold(e.target.value)}
                    className="h-8 text-xs"
                  />
                </div>

                <div className="sm:col-span-2 flex justify-end">
                  <Button
                    size="sm"
                    onClick={handleSaveSettings}
                    disabled={updateSettings.isPending}
                    className="h-8 text-xs"
                  >
                    {updateSettings.isPending ? (
                      <>
                        <Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" />
                        Saving&hellip;
                      </>
                    ) : (
                      "Save Settings"
                    )}
                  </Button>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </CardContent>
    </Card>
  );
}

// ── Add URL dialog ─────────────────────────────────────────────

interface AddUrlDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

function AddUrlDialog({ open, onOpenChange }: AddUrlDialogProps) {
  const addUrl = useAddMonitoredUrl();
  const [url, setUrl] = useState("");
  const [frequency, setFrequency] = useState<MonitoringFrequency>("weekly");
  const [threshold, setThreshold] = useState("5");

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const trimmed = url.trim();
    if (!trimmed) {
      toast.error("URL is required");
      return;
    }

    try {
      new URL(trimmed);
    } catch {
      toast.error("Please enter a valid URL (e.g. https://example.com)");
      return;
    }

    const thresholdNum = parseInt(threshold, 10);
    if (isNaN(thresholdNum) || thresholdNum < 1 || thresholdNum > 20) {
      toast.error("Threshold must be between 1 and 20");
      return;
    }

    addUrl.mutate(
      { url: trimmed, frequency, alert_threshold: thresholdNum },
      {
        onSuccess: () => {
          toast.success("URL added to monitoring");
          setUrl("");
          setFrequency("weekly");
          setThreshold("5");
          onOpenChange(false);
        },
        onError: (err) => {
          toast.error(err instanceof Error ? err.message : "Failed to add URL");
        },
      }
    );
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Add URL to Monitor</DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4 py-2">
          <div className="space-y-1.5">
            <Label htmlFor="monitor-url">URL</Label>
            <Input
              id="monitor-url"
              type="url"
              placeholder="https://yoursite.com/landing"
              value={url}
