export default function MonitoringPage() {
  const { profile } = useAuth();
  const { data: monitoredUrls = [], isLoading } = useMonitoredUrls();
  const removeUrl = useRemoveMonitoredUrl();
  const [addDialogOpen, setAddDialogOpen] = useState(false);
  const [removingId, setRemovingId] = useState<string | null>(null);

  const isPro = profile ? isProPlus(profile.plan) : false;

  const handleRemove = (id: string) => {
    setRemovingId(id);
    removeUrl.mutate(id, {
      onSuccess: () => {
        toast.success("URL removed from monitoring");
        setRemovingId(null);
      },
      onError: () => {
        toast.error("Failed to remove URL");
        setRemovingId(null);
      },
    });
  };

  return (
    <div className="max-w-3xl mx-auto space-y-6 p-6">
      {/* Page header */}
      <div className="flex items-start justify-between gap-4">
        <div>
          <div className="flex items-center gap-2">
            <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary/10">
              <Activity className="h-4 w-4 text-primary" />
            </div>
            <h1 className="text-2xl font-bold tracking-tight">Score Monitoring</h1>
          </div>
          <p className="mt-1 text-sm text-muted-foreground">
            Track your URLs and get alerted when scores drop
          </p>
        </div>

        {isPro && (
          <Button onClick={() => setAddDialogOpen(true)} className="shrink-0">
            <Plus className="mr-2 h-4 w-4" />
            Add URL
          </Button>
        )}
      </div>

      {/* Plan gate */}
      {!isPro ? (
        <PremiumLock />
      ) : isLoading ? (
        <div className="space-y-3">
          {[1, 2, 3].map((i) => (
            <MonitoringCardSkeleton key={i} />
          ))}
        </div>
      ) : monitoredUrls.length === 0 ? (
        <EmptyMonitoringState onAdd={() => setAddDialogOpen(true)} />
      ) : (
        <>
          {/* Summary bar */}
          <div className="flex items-center gap-3 rounded-lg border border-border/60 bg-muted/30 px-4 py-3">
            <Bell className="h-4 w-4 text-muted-foreground shrink-0" />
            <span className="text-sm text-muted-foreground">
              <span className="font-medium text-foreground">
                {monitoredUrls.filter((m) => m.is_active).length}
              </span>{" "}
              of {monitoredUrls.length} URL{monitoredUrls.length !== 1 ? "s" : ""} actively monitored
            </span>
          </div>

          {/* URL cards */}
          <motion.div
            className="space-y-3"
            initial="hidden"
            animate="visible"
            variants={{
              hidden: {},
              visible: { transition: { staggerChildren: 0.06 } },
            }}
          >
            <AnimatePresence>
              {monitoredUrls.map((entry) => (
                <motion.div
                  key={entry.id}
                  variants={{
                    hidden: { opacity: 0, y: 12 },
                    visible: { opacity: 1, y: 0 },
                  }}
                  exit={{ opacity: 0, y: -8, transition: { duration: 0.15 } }}
                  transition={{ duration: 0.25, ease: "easeOut" }}
                >
                  <MonitoredUrlCard
                    entry={entry}
                    onRemove={handleRemove}
                    isRemoving={removingId === entry.id}
                  />
                </motion.div>
              ))}
            </AnimatePresence>
          </motion.div>
        </>
      )}

      {/* Add URL dialog */}
      <AddUrlDialog open={addDialogOpen} onOpenChange={setAddDialogOpen} />
    </div>
  );
}

