export default function IntegrationsPage() {
  const [dialogProvider, setDialogProvider] =
    useState<IntegrationProvider | null>(null);

  const { profile } = useAuth();
  const { data: integrations = [], isLoading, isError, refetch } = useIntegrations();

  const isPro = profile ? isProPlus(profile.plan) : false;
  const slackConnected = integrations.some(
    (i) => i.provider === "slack" && i.is_active,
  );
  const ga4Connected = integrations.some(
    (i) => i.provider === "google_analytics" && i.is_active,
  );
  const connectedCount = integrations.filter((i) => i.is_active).length;
  const total = INTEGRATIONS.length + 2;

  const activeDialog = INTEGRATIONS.find((c) => c.id === dialogProvider) ?? null;

  // Show toast if OAuth redirected back with result query params
  useEffect(() => {
    if (typeof window === "undefined") return;
    const params = new URLSearchParams(window.location.search);
    const cleanUrl = window.location.pathname;

    const slackParam = params.get("slack");
    if (slackParam === "connected") {
      toast.success("Slack connected successfully");
      window.history.replaceState(null, "", cleanUrl);
    } else if (slackParam === "error") {
      toast.error("Failed to connect Slack. Please try again.");
      window.history.replaceState(null, "", cleanUrl);
    }

    const ga4Param = params.get("ga4");
    if (ga4Param === "connected") {
      toast.success("Google Analytics 4 connected successfully");
      window.history.replaceState(null, "", cleanUrl);
    } else if (ga4Param === "error") {
      toast.error("Failed to connect Google Analytics. Please try again.");
      window.history.replaceState(null, "", cleanUrl);
    }
  }, []);

  return (
    <PageTransition>
      <div className="space-y-6">
        <div className="flex items-start justify-between gap-4">
          <PageHeader
            title="Integrations"
            description="Connect your analytics tools for deeper CRO insights"
          />
          {!isLoading && (
            <div className="flex shrink-0 items-center gap-1.5 text-sm text-muted-foreground pt-1">
              <span className="font-medium text-foreground">
                {connectedCount}
              </span>{" "}
              of {total} integrations connected
            </div>
          )}
        </div>

        {isLoading ? (
          <IntegrationsSkeleton />
        ) : isError ? (
          <ErrorState
            title="Failed to load integrations"
            description="There was a problem fetching your integrations. Check your connection and try again."
            onRetry={() => void refetch()}
          />
        ) : (
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            <Ga4IntegrationCard
              isConnected={ga4Connected}
              isPro={isPro}
              userId={profile?.id ?? ""}
            />
            {INTEGRATIONS.map((config) => {
              const connected = integrations.find(
                (i) => i.provider === config.id && i.is_active
              );
              return (
                <IntegrationCard
                  key={config.id}
                  config={config}
                  isConnected={!!connected}
                  onConnectRequest={() => setDialogProvider(config.id)}
                />
              );
            })}
            <SlackIntegrationCard
              isConnected={slackConnected}
              isPro={isPro}
              userId={profile?.id ?? ""}
            />
          </div>
        )}

        {activeDialog && (
          <ConnectDialog
            config={activeDialog}
            open={dialogProvider !== null}
            onOpenChange={(open) => {
              if (!open) setDialogProvider(null);
            }}
          />
        )}

        <Separator />
        <WebhookManager />
      </div>
    </PageTransition>
  );
}

