export default function SettingsPage() {
  const router = useRouter();
  const { profile, loading: authLoading } = useAuth();
  const updateProfile = useUpdateProfile();
  const updateEmailPrefs = useUpdateEmailPreferences();
  const portal = useCustomerPortal();
  const usage = useUsage();

  // Form state
  const [fullName, setFullName] = useState("");
  const [companyName, setCompanyName] = useState("");
  const [websiteUrl, setWebsiteUrl] = useState("");
  const [showPasswordChange, setShowPasswordChange] = useState(false);

  // Password change fields
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [passwordUpdating, setPasswordUpdating] = useState(false);

  // Populate form once profile loads
  const seeded = useRef(false);
  useEffect(() => {
    if (profile && !seeded.current) {
      setFullName(profile.full_name ?? "");
      setCompanyName(profile.company_name ?? "");
      setWebsiteUrl(profile.website_url ?? "");
      seeded.current = true;
    }
  }, [profile]);

  // Email preferences
  const DEFAULT_EMAIL_PREFS: EmailPreferences = { marketing: false, digest: true, scan_alerts: true };
  const [emailPrefs, setEmailPrefs] = useState<EmailPreferences>(DEFAULT_EMAIL_PREFS);
  const emailPrefsSeeded = useRef(false);

  useEffect(() => {
    if (profile && !emailPrefsSeeded.current) {
      const prefs = profile.email_preferences;
      if (prefs) {
        setEmailPrefs({
          marketing: prefs.marketing ?? false,
          digest: prefs.digest ?? true,
          scan_alerts: prefs.scan_alerts ?? true,
        });
      }
      emailPrefsSeeded.current = true;
    }
  }, [profile]);

  const handleEmailPrefChange = (key: keyof EmailPreferences, value: boolean) => {
    const next: EmailPreferences = { ...emailPrefs, [key]: value };
    setEmailPrefs(next);
    updateEmailPrefs.mutate(next, {
      onSuccess: () => toast.success("Preferences saved"),
      onError: () => toast.error("Failed to save preferences"),
    });
  };

  const handlePasswordChange = async () => {
    if (!newPassword) {
      toast.error("New password is required.");
      return;
    }
    if (newPassword.length < MIN_PASSWORD_LENGTH) {
      toast.error("Password must be at least 8 characters.");
      return;
    }
    if (newPassword !== confirmPassword) {
      toast.error("Passwords do not match.");
      return;
    }

    setPasswordUpdating(true);
    const supabase = createClient();
    const { error } = await supabase.auth.updateUser({ password: newPassword });
    setPasswordUpdating(false);

    if (error) {
      toast.error(error.message ?? "Failed to update password. Please try again.");
      return;
    }

    toast.success("Password updated successfully.");
    setNewPassword("");
    setConfirmPassword("");
    setShowPasswordChange(false);
  };

  const handleSave = () => {
    updateProfile.mutate(
      {
        full_name: fullName.trim() || undefined,
        company_name: companyName.trim() || null,
        website_url: websiteUrl.trim() || null,
