// ── Support tab sub-component ─────────────────────────────────

const STATUS_BADGE_CLASSES: Record<string, string> = {
  open: "bg-amber-100 text-amber-700",
  in_progress: "bg-blue-100 text-blue-700",
  resolved: "bg-green-100 text-green-700",
  closed: "bg-slate-100 text-slate-600",
};

function SupportTab() {
  const [subject, setSubject] = useState("");
  const [message, setMessage] = useState("");
  const [priority, setPriority] = useState<SupportPriority>("normal");
  const [subjectError, setSubjectError] = useState<string | null>(null);
  const [messageError, setMessageError] = useState<string | null>(null);

  const submitRequest = useSubmitSupportRequest();
  const myRequests = useMySupportRequests();

  const handleSubmit = () => {
    let valid = true;
    if (!subject.trim()) {
      setSubjectError("Subject is required.");
      valid = false;
    } else if (subject.length > 100) {
      setSubjectError("Subject must be 100 characters or less.");
      valid = false;
    } else {
      setSubjectError(null);
    }

    if (!message.trim()) {
      setMessageError("Message is required.");
      valid = false;
    } else if (message.length < 20) {
      setMessageError("Message must be at least 20 characters.");
      valid = false;
    } else if (message.length > 2000) {
      setMessageError("Message must be 2000 characters or less.");
      valid = false;
    } else {
      setMessageError(null);
    }

    if (!valid) return;

    submitRequest.mutate(
      { subject: subject.trim(), message: message.trim(), priority },
      {
        onSuccess: () => {
          setSubject("");
          setMessage("");
          setPriority("normal");
        },
      }
    );
  };

  return (
    <div className="space-y-6">
      <Card className="border-border/50 shadow-soft">
        <CardHeader>
          <CardTitle className="text-base">Contact Support</CardTitle>
          <CardDescription>
            Submit a support request and our team will get back to you.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-1.5">
            <Label htmlFor="support-subject">Subject</Label>
            <Input
              id="support-subject"
              value={subject}
              onChange={(e) => { setSubject(e.target.value); setSubjectError(null); }}
              placeholder="Brief description of your issue..."
              maxLength={100}
              className={cn("border-border/50", subjectError && "border-red-500")}
            />
            {subjectError && (
              <p className="text-xs text-red-600">{subjectError}</p>
            )}
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="support-priority">Priority</Label>
            <Select value={priority} onValueChange={(v) => setPriority(v as SupportPriority)}>
              <SelectTrigger id="support-priority" className="border-border/50">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="normal">Normal</SelectItem>
                <SelectItem value="high">High</SelectItem>
                <SelectItem value="urgent">Urgent</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="support-message">
              Message
              <span className="ml-2 text-xs font-normal text-muted-foreground">
                ({message.length}/2000)
              </span>
            </Label>
            <Textarea
              id="support-message"
              value={message}
              onChange={(e) => { setMessage(e.target.value); setMessageError(null); }}
              placeholder="Describe your issue in detail..."
              maxLength={2000}
              className={cn("min-h-[120px] resize-none border-border/50", messageError && "border-red-500")}
            />
            {messageError && (
              <p className="text-xs text-red-600">{messageError}</p>
            )}
          </div>

          <Button
            onClick={handleSubmit}
            disabled={submitRequest.isPending}
            className="w-full sm:w-auto"
          >
            {submitRequest.isPending ? (
              <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />
            ) : (
              <Send className="mr-2 h-3.5 w-3.5" />
            )}
            {submitRequest.isPending ? "Submitting\u2026" : "Submit Request"}
          </Button>
        </CardContent>
      </Card>

      <Card className="border-border/50 shadow-soft">
        <CardHeader>
          <CardTitle className="text-base">My Support Requests</CardTitle>
          <CardDescription>
            Track the status of your submitted requests.
          </CardDescription>
        </CardHeader>
        <CardContent>
          {myRequests.isLoading ? (
            <div className="space-y-2">
              {Array.from({ length: 3 }).map((_, i) => (
                <Skeleton key={i} className="h-10 w-full rounded-lg" />
              ))}
            </div>
          ) : myRequests.isError ? (
            <ErrorState
              title="Failed to load requests"
              description="There was a problem fetching your support history. Try again."
              onRetry={() => void myRequests.refetch()}
            />
          ) : !myRequests.data || myRequests.data.length === 0 ? (
            <div className="rounded-xl border border-dashed border-border/50 py-8 text-center">
              <LifeBuoy className="mx-auto h-8 w-8 text-muted-foreground/40 mb-2" />
              <p className="text-sm text-muted-foreground">No support requests yet.</p>
            </div>
          ) : (
            <div className="rounded-xl border border-border/50 overflow-hidden">
              <Table>
                <TableHeader>
                  <TableRow className="bg-muted/40 hover:bg-muted/40">
                    <TableHead>Subject</TableHead>
                    <TableHead>Priority</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Submitted</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {myRequests.data.map((req) => (
                    <TableRow key={req.id}>
                      <TableCell className="text-sm font-medium max-w-[200px]">
                        <span className="truncate block">{req.subject}</span>
                      </TableCell>
                      <TableCell>
                        <Badge className="text-2xs px-1.5 py-0 capitalize bg-muted/50 text-foreground/70 border-0">
                          {req.priority}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        <Badge className={`text-2xs px-1.5 py-0 border-0 ${STATUS_BADGE_CLASSES[req.status] ?? "bg-muted/50 text-foreground/70"}`}>
                          {req.status.replace("_", " ")}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
                        {new Date(req.created_at).toLocaleDateString("en-US", {
                          month: "short",
                          day: "numeric",
                          year: "numeric",
                        })}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

