235	          >
236	            <span>Detailed Comparison</span>
237	            <ChevronDown
238	              className={cn("h-4 w-4 transition-transform duration-200", expanded && "rotate-180")}
239	            />
240	          </button>
241	
242	          <AnimatePresence>
243	            {expanded && (
244	              <motion.div
245	                initial={{ opacity: 0, height: 0 }}
246	                animate={{ opacity: 1, height: "auto" }}
247	                exit={{ opacity: 0, height: 0 }}
248	                transition={{ duration: 0.25, ease: "easeInOut" }}
249	                className="overflow-hidden"
250	              >
251	                <div className="pt-4 space-y-6">
252	                  {/* Radar chart */}
