'use client';

import { useState } from "react";
import { Plus, Trash2, Loader2, Key, Clock, Shield } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { useAuth } from "@/contexts/AuthContext";
import { isProPlus } from "@/types/index";
import { useApiKeys, useRevokeApiKey } from "@/hooks/use-api-keys";
import { ApiKeyDialog } from "@/components/api/ApiKeyDialog";
import { ApiDocumentation } from "@/components/api/ApiDocumentation";
import { PremiumLock } from "@/components/shared/PremiumLock";
import type { ApiKey } from "@/types";

// ── Helper: format date ───────────────────────────────────────

function formatDate(iso: string | null): string {
  if (!iso) return "Never";
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  }).format(new Date(iso));
}

// ── KeyRow ────────────────────────────────────────────────────

interface KeyRowProps {
  apiKey: ApiKey;
}

function KeyRow({ apiKey }: KeyRowProps) {
  const { mutate: revoke, isPending } = useRevokeApiKey();

  return (
    <div className="flex items-center justify-between gap-4 py-3 border-b last:border-0">
      <div className="flex items-center gap-3 min-w-0">
        <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md bg-muted">
          <Key className="h-4 w-4 text-muted-foreground" />
        </div>
        <div className="min-w-0">
          <p className="font-medium text-sm truncate">{apiKey.name}</p>
          <p className="font-mono text-xs text-muted-foreground">
            {apiKey.key_prefix}&hellip;
          </p>
        </div>
      </div>

      <div className="flex items-center gap-6 shrink-0">
        <div className="hidden sm:block text-right">
          <p className="text-xs text-muted-foreground">Created</p>
          <p className="text-xs font-medium">{formatDate(apiKey.created_at)}</p>
        </div>
        <div className="hidden md:block text-right">
          <p className="text-xs text-muted-foreground">Last used</p>
          <p className="text-xs font-medium flex items-center gap-1">
            <Clock className="h-3 w-3" />
            {formatDate(apiKey.last_used_at)}
          </p>
        </div>
        <div className="hidden sm:flex items-center gap-1">
          {apiKey.permissions.map((p) => (
            <Badge key={p} variant="secondary" className="text-2xs capitalize px-1.5 py-0">
              <Shield className="h-2.5 w-2.5 mr-1" />
              {p}
            </Badge>
          ))}
        </div>

        <AlertDialog>
          <AlertDialogTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8 text-muted-foreground hover:text-destructive"
              disabled={isPending}
              aria-label={`Revoke key ${apiKey.name}`}
            >
              {isPending ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <Trash2 className="h-4 w-4" />
              )}
            </Button>
          </AlertDialogTrigger>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Revoke API Key</AlertDialogTitle>
              <AlertDialogDescription>
                Are you sure you want to revoke &quot;{apiKey.name}&quot;? Any applications
                using this key will immediately lose access. This action cannot be undone.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction
                className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                onClick={() => revoke({ id: apiKey.id })}
              >
                Revoke Key
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </div>
    </div>
  );
}

// ── KeysSkeleton ──────────────────────────────────────────────

function KeysSkeleton() {
  return (
